/* ==UserStyle==
@name cobalt Catppuccin
@namespace github.com/catppuccin/userstyles/styles/cobalt
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/cobalt
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/cobalt/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Acobalt
@description Soothing pastel theme for cobalt
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("cobalt.tools") {
  [data-theme="dark"] {
    #catppuccin(@darkFlavor);
  }
  [data-theme="light"] {
    #catppuccin(@lightFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    --primary: @base;
    --secondary: @text;
    --gray: @subtext0;
    --blue: @blue;
    --green: @green;
    --red: @maroon;
    --medium-red: @red;
    --dark-red: @red;
    --white: @crust;
    --button: @surface0;
    --button-hover: darken(@surface0, 5%);
    --button-active-hover: darken(@subtext0, 5%);
    --button-elevated: @surface1;
    --button-elevated-hover: darken(@surface1, 5%);
    --button-text: @text;
    --sidebar-bg: @mantle;
    --sidebar-hover: @surface0;
    --sidebar-highlight: @text;
    --input-border: @surface2;
    --popup-bg: @mantle;
    --toggle-bg-enabled: @accent;

    #donate-page {
      --donate-gradient-start: @surface1 !important;
      --donate-gradient-end: @surface0 !important;
    }

    #banner-left {
      color: @text;
    }

    #banner-subtitle {
      color: @subtext0;
      opacity: 1;
    }

    .donate-card button {
      color: @text !important;
    }

    .donate-card {
      color: @text;
    }

    .donate-card-title {
      color: @text;
    }

    .donate-card-subtitle {
      color: @subtext0;
      opacity: 1;
    }

    #input-container.focused {
      box-shadow: 0 0 0 2px @text inset !important;
    }

    #input-dollar-sign {
      color: @text;
    }

    #donation-custom-input {
      color: @text !important;
    }

    #cobalt-logo path {
      fill: @text;
    }

    .sidebar-tab.active {
      background-color: @accent !important;
    }
  }
}

